package com.company.skillplatform.version.infrastructure.entity;
import static org.assertj.core.api.Assertions.*;import com.company.skillplatform.common.application.BusinessException;import com.company.skillplatform.skill.infrastructure.entity.SkillEntity;import com.company.skillplatform.user.infrastructure.entity.IamUserEntity;import com.company.skillplatform.version.domain.*;import java.time.Instant;import org.junit.jupiter.api.Test;import org.mockito.Mockito;
class SkillVersionEntityTest{
 @Test void supportsReviewApprovePublishDeprecateOffline(){SkillVersionEntity v=new SkillVersionEntity(Mockito.mock(SkillEntity.class),null,ChangeType.INITIAL,Mockito.mock(IamUserEntity.class));v.submit("1.0.0",Mockito.mock(IamUserEntity.class));v.approve(Mockito.mock(IamUserEntity.class));v.publish(Instant.EPOCH,Mockito.mock(IamUserEntity.class));v.deprecate(null,Mockito.mock(IamUserEntity.class));v.offline(Instant.EPOCH,Mockito.mock(IamUserEntity.class));assertThat(v.getLifecycleStatus()).isEqualTo(LifecycleStatus.OFFLINE);assertThat(v.getVersion()).isEqualTo("1.0.0");}
 @Test void supportsRejectWithdrawUploadAndCancel(){IamUserEntity u=Mockito.mock(IamUserEntity.class);SkillVersionEntity rejected=new SkillVersionEntity(Mockito.mock(SkillEntity.class),null,ChangeType.INITIAL,u);rejected.submit("1.0.0",u);rejected.reject(u);rejected.markUploaded("zip",u);assertThat(rejected.getChangeType()).isEqualTo(ChangeType.ZIP_REUPLOAD);SkillVersionEntity withdrawn=new SkillVersionEntity(Mockito.mock(SkillEntity.class),null,ChangeType.ONLINE_EDIT,u);withdrawn.submit("1.1.0",u);withdrawn.approve(u);withdrawn.withdraw(u);withdrawn.cancel(u);assertThat(withdrawn.getCandidateVersion()).isNull();assertThatThrownBy(()->withdrawn.publish(Instant.EPOCH,u)).isInstanceOf(BusinessException.class);}
}
